/**
 * The hero domain. Plain types and the closed vocabularies the roster, detail,
 * and edit screens all share, so a power class or status is spelled once.
 */
export const POWER_CLASSES = ['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced'] as const;
export type PowerClass = (typeof POWER_CLASSES)[number];

export const HERO_STATUSES = ['Active', 'Injured', 'Reserve', 'MIA'] as const;
export type HeroStatus = (typeof HERO_STATUSES)[number];

export const CLEARANCE_TIERS = [1, 2, 3, 4, 5] as const;
export type ClearanceTier = (typeof CLEARANCE_TIERS)[number];

export interface Hero {
  readonly id: string;
  /** Public codename shown in the roster, e.g. "Silverwing". */
  readonly name: string;
  /** Operational alias: the name a hero is filed under, distinct from the codename. */
  readonly alias: string;
  readonly powerClass: PowerClass;
  /** Power index, 0 to 100. */
  readonly powerIndex: number;
  readonly status: HeroStatus;
  readonly clearanceTier: ClearanceTier;
  readonly missionCount: number;
  /** Success rate as a fraction, 0 to 1. */
  readonly successRate: number;
}

/** A partial change to a hero's editable fields. The id never changes. */
export type HeroUpdate = Partial<Omit<Hero, 'id'>>;
==== src/app/domain/hero.service.ts
import { Service, signal } from '@angular/core';
import { EXAMPLE_HEROES } from './hero.data';
import { Hero, HeroUpdate } from './hero.model';

/**
 * The in-memory hero roster. There is no backend: the roster is a signal seeded
 * with EXAMPLE_HEROES, which is example data. Edits last until the page reloads.
 *
 * ViewModels read `heroes` (reactively) and call `find` and `update`. Nothing
 * here subscribes to anything.
 */
@Service()
export class HeroService {
  private readonly roster = signal<readonly Hero[]>(EXAMPLE_HEROES);

  /** The whole roster, read-only. */
  readonly heroes = this.roster.asReadonly();

  /** Look a hero up by id. Reads the roster signal, so it is reactive inside `computed`. */
  find(id: string): Hero | undefined {
    return this.roster().find((hero) => hero.id === id);
  }

  /**
   * Apply a partial change to one hero and return the updated record, or
   * `undefined` when no hero has that id. Builds a new roster rather than
   * mutating the old one, so signal consumers see the change.
   */
  update(id: string, patch: HeroUpdate): Hero | undefined {
    const current = this.find(id);
    if (!current) return undefined;
    const updated: Hero = { ...current, ...patch };
    this.roster.update((heroes) => heroes.map((hero) => (hero.id === id ? updated : hero)));
    return updated;
  }
}
